fn st_private_access_denied(si: i64, access_tok: i64) -> bool with IO, Mut, Panic {
    if si < 0 { return false }
    if ST_PUBLIC[si as usize] != 0 { return false }
    if ST_DECL_NE[si as usize] <= ST_DECL_NS[si as usize] { return false }
    if access_tok < 0 || access_tok >= TC { return false }
    if src_same_file_pos(TS[access_tok as usize], ST_DECL_NS[si as usize]) { return false }
    PENDING_PRIV_SI = si
    return true
}

