        let r10_cv_frac = LAST_LITERAL_F64_FRAC
        let r10_cv_denom = LAST_LITERAL_F64_DENOM
        let r10_bv_int = FN_RET_PRED_BOUND[CURRENT_FN as usize]
        let r10_bv_frac = FN_RET_PRED_BOUND_FRAC[CURRENT_FN as usize]
        let r10_bv_denom = FN_RET_PRED_BOUND_DENOM[CURRENT_FN as usize]
        let r10_lhs = (r10_cv_int * r10_cv_denom + r10_cv_frac) * r10_bv_denom
        let r10_rhs = (r10_bv_int * r10_bv_denom + r10_bv_frac) * r10_cv_denom
