                    if r10_op2 == 24 && r10_lhs2 > r10_rhs2 { r10_ok2 = 1 }
                    if r10_op2 == 25 && r10_lhs2 <= r10_rhs2 { r10_ok2 = 1 }
                    if r10_op2 == 23 && r10_lhs2 < r10_rhs2 { r10_ok2 = 1 }
                    if r10_ok2 == 1 { r10_viol = 0 }
                }
            }
