            if op2 == 23 && cv >= bv2 { violated = 1 }
            if op2 == 21 && cv != bv2 { violated = 1 }
            if op2 == 22 && cv == bv2 { violated = 1 }
        } else {
            if violated == 1 {
                var ok2: i64 = 0
                if op2 == 26 && cv >= bv2 { ok2 = 1 }
                if op2 == 24 && cv > bv2 { ok2 = 1 }
                if op2 == 25 && cv <= bv2 { ok2 = 1 }
                if op2 == 23 && cv < bv2 { ok2 = 1 }
                if op2 == 21 && cv == bv2 { ok2 = 1 }
                if op2 == 22 && cv != bv2 { ok2 = 1 }
                if ok2 == 1 { violated = 0 }
            }
        }
    }
    if violated == 1 {
