pub fn cgplan_isqrt(n: i64) -> i64 with Div, Mut {
    if n <= 0 { return 0 }
    var x: i64 = n
    var y: i64 = (x + 1) / 2
    while y < x {
        x = y
        y = (x + n / x) / 2
    }
    x
}

