fn substitute_type_param(
    ty: TypeEntry,
    tp_count: i64,
    tp_names: [Name; 8],
    args: TypeEntryList,
) -> TypeEntry with Mut, Panic, Div {
    if ty.kind == TypeKind::TyNamed {
        // Check if this name matches any type parameter
        var idx: i64 = 0
        while idx < tp_count {
            if name_eq(ty.name, tp_names[idx]) {
                // Found match — return the corresponding type argument
                return type_entry_list_nth(args, idx)
            }
            idx = idx + 1
        }
    }
    // Not a type param reference — return as-is
    ty
}

