fn checker_lower_knowledge_type_mut(c: *mut Checker, opt: Option<Box<KnowledgeTypeInfo> >) -> TypeEntry with Mut, Panic, Div, Alloc, IO {
    match opt {
        Some(info_box) => {
            let info = *info_box
            let inner_ty = checker_lower_type_expr_mut(c, *info.inner_type)
            if !knowledge_metadata_is_valid(info.validity) {
                checker_note_type_error_mut(c)
            }
            let meta = knowledge_meta_from_type_info(info)
            if !knowledge_meta_is_valid(meta) {
                checker_note_type_error_mut(c)
            }
            var eps_val: f64 = -1.0
            match info.epsilon {
                Some(eb) => {
                    let bound = *eb
                    if bound.value < 0.0 || bound.value > 1.0 {
                        checker_note_type_error_mut(c)
                    } else {
                        eps_val = bound.value
                    }
                }
                None => {}
            }
            ty_knowledge(inner_ty, eps_val)
        }
        None => {
            checker_note_type_error_mut(c)
            ty_error()
        }
    }
}

